// Writes pixelmatch-vectors.ts: the two published test images 1a.png and 1b.png of pixelmatch's own test suite, at the
// tag v7.2.0, as base64 literals. Run from the repository root with Node 22:
//
//   node tools/image-compare/test/fixtures/make-fixtures.mjs
//
// The images and their expected counts are pixelmatch's published vectors (test/test.js at the same tag:
// diffTest('1a', '1b', '1diff', { threshold: 0.05 }, 143) and diffTest('1a', '1b', '1diffdefaultthreshold',
// { threshold: undefined }, 106)). pixelmatch is ISC licensed, Copyright (c) 2025, Mapbox.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const TAG = 'v7.2.0';
const BASE = `https://raw.githubusercontent.com/mapbox/pixelmatch/${TAG}/test/fixtures/`;

async function fetchBase64(name) {
  const response = await fetch(BASE + name);
  if (!response.ok) throw new Error(`${name}: HTTP ${response.status}`);
  return Buffer.from(await response.arrayBuffer()).toString('base64');
}

const a = await fetchBase64('1a.png');
const b = await fetchBase64('1b.png');

const out =
  `// Generated by test/fixtures/make-fixtures.mjs from pixelmatch ${TAG} (ISC, Copyright (c) 2025, Mapbox). Do not edit.\n` +
  `// Both images are 512 by 256, 8-bit RGBA, not interlaced.\n` +
  `export const PIXELMATCH_1A_PNG_BASE64 =\n  '${a}';\n\n` +
  `export const PIXELMATCH_1B_PNG_BASE64 =\n  '${b}';\n`;

writeFileSync(fileURLToPath(new URL('./pixelmatch-vectors.ts', import.meta.url)), out);
console.log('wrote pixelmatch-vectors.ts', a.length + b.length, 'base64 characters');
